// Create a two-way binding to the Opacity property of Node A.
let binding = kanzi::TwoWayBinding::create_with_property(
    "../Node A",
    &*kanzi::node_2d::OPACITY_PROPERTY,
)?;

// Create a callback processor that accepts only float values greater than or equal to 0.5.
let processor = kanzi::CallbackBindingProcessor::create_with_callback(domain, move |value| {
    if let Some(value) = value.cast_ref::<f32>()? {
        return Ok(value.get()? >= 0.5);
    }
    Ok(false)
})?;

// Add a callback processor to the binding. You must do this before adding the binding to a node.
binding.add_processor(&processor)?;

// Bind from the Opacity property of Node A to the Opacity property of Node B.
let runtime = node_b.set_binding1(&binding, &kanzi::node_2d::OPACITY_PROPERTY)?;

// Setting the opacity of Node A to less than 0.5 does not change the
// opacity of Node B.
{
    let opacity = 0.333333;
    node_a.set_opacity(opacity)?;
    assert_ne!(opacity, node_b.get_opacity()?);
}

// Setting the opacity of Node A to a value greater than or equal to 0.5 changes the
// opacity of Node B.
{
    let opacity = 0.555555;

    node_a.set_opacity(opacity)?;
    assert_eq!(opacity, node_b.get_opacity()?);
}

node_b.remove_binding(&runtime)?;

