  2. Implement a binding to track changes in property and log its value:
Java

```
@Override
protected void attachOverride()
{
    super.attachOverride();

    // Get the name of the property type that you want to log.
    String loggedPropertyTypeName = getProperty(LoggedPropertyTypeProperty);
    if (loggedPropertyTypeName.isEmpty())
    {
        Log.info("Use the Logged Property Type property to set which property type you "
            + "want to log.");
        return;
    }

    // Get the property type that you want to log and check that it is valid.
    DynamicPropertyType<Float> loggedPropertyType =
        new DynamicPropertyType<>(loggedPropertyTypeName, Float.class);
    if (!loggedPropertyType.isValid())
    {
        Log.warning("LogPropertyValueComponent cannot find the specified property type "
            + "with float data type.");
        return;
    }

    // Add the notification handler for the property type that you want to log.
    AbstractBinding binding = BindingBuilder.createOneWay(".", loggedPropertyType);
    ObjectRef<CallbackBindingProcessor> processorRef =
        CallbackBindingProcessor.create(getDomain(), value -> {
            logPropertyValue(loggedPropertyTypeName, (Float) value);
            return false;
        });

    binding.addProcessor(processorRef.get());

    getNode().setBinding(binding);

    // Print the initial value of the property type that you want to log.
    Float initialPropertyValue = getNode().getOptionalProperty(loggedPropertyType);
    if (initialPropertyValue != null)
    {
        logPropertyValue(loggedPropertyTypeName, initialPropertyValue);
    }
}

private void logPropertyValue(String loggedPropertyTypeName, Float value)
{
    Log.info(getNode().getName() + ":" + loggedPropertyTypeName + " = " + value);
}

